--
-- Table structure for table `data_transfer_logs`
--

DROP TABLE IF EXISTS `data_transfer_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `data_transfer_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_type` enum('import','export') NOT NULL,
  `data_type` enum('students','faculty','courses','enrollments','grades','milestones','programs','academic_outputs') NOT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_format` enum('csv','xlsx','pdf') DEFAULT NULL,
  `total_rows` int(11) DEFAULT NULL,
  `successful_rows` int(11) DEFAULT NULL,
  `failed_rows` int(11) DEFAULT NULL,
  `error_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`error_details`)),
  `filters_applied` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`filters_applied`)),
  `status` enum('pending','processing','completed','failed') NOT NULL DEFAULT 'pending',
  `initiated_by` bigint(20) unsigned DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `data_transfer_logs_initiated_by_foreign` (`initiated_by`),
  CONSTRAINT `data_transfer_logs_initiated_by_foreign` FOREIGN KEY (`initiated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

