DROP TABLE IF EXISTS `enrollment_course_enrollee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `enrollment_course_enrollee` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `enrollee_id` bigint(20) unsigned NOT NULL,
  `enrollment_course_id` bigint(20) unsigned NOT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ecr_enrollee_course_unique` (`enrollee_id`,`enrollment_course_id`),
  KEY `enrollment_course_enrollee_enrollment_course_id_foreign` (`enrollment_course_id`),
  CONSTRAINT `enrollment_course_enrollee_enrollee_id_foreign` FOREIGN KEY (`enrollee_id`) REFERENCES `enrollees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `enrollment_course_enrollee_enrollment_course_id_foreign` FOREIGN KEY (`enrollment_course_id`) REFERENCES `enrollment_courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13926 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
