--
-- Table structure for table `faculty`
--

DROP TABLE IF EXISTS `faculty`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `faculty` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `first_name` varchar(100) NOT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) NOT NULL,
  `suffix` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `employment_status` enum('full-time','part-time','temporary','others') DEFAULT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `unit_id` bigint(20) unsigned DEFAULT NULL,
  `highest_degree` enum('high-school','vocational','bachelors','masters','doctorate','n/a') DEFAULT NULL,
  `staff_classification` enum('admin','reps','faculty','others') DEFAULT NULL,
  `birthday` date DEFAULT NULL,
  `sex` varchar(255) DEFAULT NULL,
  `date_hired_cpaf` date DEFAULT NULL,
  `year_graduated` int(11) DEFAULT NULL,
  `contact_number` varchar(20) DEFAULT NULL,
  `is_pursuing_postgrad` tinyint(1) NOT NULL DEFAULT 0,
  `postgrad_program` varchar(255) DEFAULT NULL,
  `postgrad_level` enum('masters','doctorate') DEFAULT NULL,
  `faculty_status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `is_external` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `faculty_email_unique` (`email`),
  UNIQUE KEY `faculty_user_id_unique` (`user_id`),
  KEY `faculty_unit_id_foreign` (`unit_id`),
  CONSTRAINT `faculty_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=202 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

