  `enrollee_id` bigint(20) unsigned NOT NULL,
  `action` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `import_log_enrollee_enrollee_id_foreign` (`enrollee_id`),
  KEY `import_log_enrollee_import_log_id_action_index` (`import_log_id`,`action`),
  CONSTRAINT `import_log_enrollee_enrollee_id_foreign` FOREIGN KEY (`enrollee_id`) REFERENCES `enrollees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `import_log_enrollee_import_log_id_foreign` FOREIGN KEY (`import_log_id`) REFERENCES `import_logs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7705 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
