--
-- Table structure for table `student_milestones`
--

DROP TABLE IF EXISTS `student_milestones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_milestones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `milestone_template_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `category` enum('coursework','examination','research','publication','defense','other') NOT NULL,
  `status` enum('pending','in-progress','completed','waived') DEFAULT NULL,
  `date_started` date DEFAULT NULL,
  `date_completed` date DEFAULT NULL,
  `semester_id` bigint(20) unsigned DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `supporting_document` varchar(255) DEFAULT NULL,
  `verified_by` bigint(20) unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `student_milestones_student_id_foreign` (`student_id`),
  KEY `student_milestones_milestone_template_id_foreign` (`milestone_template_id`),
  KEY `student_milestones_semester_id_foreign` (`semester_id`),
  KEY `student_milestones_verified_by_foreign` (`verified_by`),
  CONSTRAINT `student_milestones_milestone_template_id_foreign` FOREIGN KEY (`milestone_template_id`) REFERENCES `milestone_templates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_milestones_semester_id_foreign` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_milestones_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_milestones_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=490 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

