--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `students` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_number` varchar(20) NOT NULL,
  `surname` varchar(100) NOT NULL,
  `given_name` varchar(100) NOT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `up_email` varchar(255) DEFAULT NULL COMMENT 'Official UP institutional email',
  `alternative_email` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`alternative_email`)),
  `birthdate` date DEFAULT NULL,
  `sex` enum('male','female','other') DEFAULT NULL,
  `marital_status` enum('single','married','widowed','separated','divorced') DEFAULT NULL,
  `nationality` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`nationality`)),
  `country_of_origin` varchar(100) DEFAULT NULL,
  `contact_number` varchar(20) DEFAULT NULL,
  `primary_contact_number` varchar(20) DEFAULT NULL COMMENT 'Primary cellphone number',
  `alternative_contact_number` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`alternative_contact_number`)),
  `address` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`address`)),
  `institution_affiliated` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`institution_affiliated`)),
  `social_facebook` varchar(255) DEFAULT NULL COMMENT 'Facebook profile URL or name',
  `social_linkedin` varchar(255) DEFAULT NULL COMMENT 'LinkedIn profile URL or handle',
  `social_other` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`social_other`)),
  `program_id` bigint(20) unsigned DEFAULT NULL,
  `program_major_id` bigint(20) unsigned DEFAULT NULL,
  `admission_semester_id` bigint(20) unsigned DEFAULT NULL,
  `admission_date` date DEFAULT NULL,
  `adviser_id` bigint(20) unsigned DEFAULT NULL,
  `adviser_appointed_date` date DEFAULT NULL,
  `registration_adviser_id` bigint(20) unsigned DEFAULT NULL,
  `registration_adviser_appointed_date` date DEFAULT NULL,
  `temporary_adviser_id` bigint(20) unsigned DEFAULT NULL,
  `temporary_adviser_appointed_date` date DEFAULT NULL,
  `student_status` enum('active','on-leave','leave-of-absence-approved','absent-without-official-leave','graduated','dismissed','dropped','withdrawn','inactive') DEFAULT 'active',
  `applicant_status` varchar(30) DEFAULT NULL COMMENT 'Admission classification: regular, probationary, denied, change-of-program, deferred',
  `graduation_date` date DEFAULT NULL,
  `graduation_semester_id` bigint(20) unsigned DEFAULT NULL,
  `total_units_earned` int(11) NOT NULL DEFAULT 0,
  `gwa` decimal(4,3) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `students_student_number_unique` (`student_number`),
  KEY `students_program_id_foreign` (`program_id`),
  KEY `students_program_major_id_foreign` (`program_major_id`),
  KEY `students_admission_semester_id_foreign` (`admission_semester_id`),
  KEY `students_adviser_id_foreign` (`adviser_id`),
  KEY `students_graduation_semester_id_foreign` (`graduation_semester_id`),
